/**
 * Cascade behind `ProjectService.archiveProject`; returns the number of issues
 * it archived. Only live issues are stamped: rows archived earlier keep their
 * original `archived_at`, and they are not counted, so the usage meter and the
 * audit entry both see just the issues this cascade actually took.
 */
export async function archiveIssuesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const rows = getDb()
    .update(issues)
    .set(archivePatch())
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )

